import{_ as t,o as s,c as i,aj as n}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Zone.js Testing Utilities","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/testing/zone-js-testing-utilities.md","filePath":"en/guide/testing/zone-js-testing-utilities.md"}'),a={name:"en/guide/testing/zone-js-testing-utilities.md"};function o(l,e,r,d,c,h){return s(),i("div",null,e[0]||(e[0]=[n('<h1 id="zone-js-testing-utilities" tabindex="-1">Zone.js Testing Utilities <a class="header-anchor" href="#zone-js-testing-utilities" aria-label="Permalink to &quot;Zone.js Testing Utilities&quot;">​</a></h1><p>This guide describes testing utilities primarily used for managing and controlling async tasks in unit tests. These utilities are essentially the Zone.js-specific mock clock utilities, particularly relevant for controlling the flow of asynchronous operations within tests.</p><p>For general Angular testing utilities, including <code>TestBed</code> and <code>ComponentFixture</code>, see the <a href="/en/guide/testing/utility-apis">Testing Utility APIs</a> guide.</p><p>Here&#39;s a summary of Zone.js-specific functions:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>waitForAsync</code></td><td style="text-align:left;">Tracks async tasks and completes the tests only once there are no longer any micro or macrotasks remaining in the test zone.</td></tr><tr><td style="text-align:left;"><code>fakeAsync</code></td><td style="text-align:left;">Runs the body of a test (<code>it</code>) within a special <em>fakeAsync test zone</em>, enabling a linear control flow coding style.</td></tr><tr><td style="text-align:left;"><code>tick</code></td><td style="text-align:left;">Simulates the passage of time and the completion of pending asynchronous activities by flushing both <em>timer</em> and <em>micro-task</em> queues within the <em>fakeAsync test zone</em>. The curious, dedicated reader might enjoy this lengthy blog post, <a href="https://jakearchibald.com/2015/tasks-microtasks-queues-and-schedules" target="_blank" rel="noreferrer">&quot;<em>Tasks, microtasks, queues and schedules</em>&quot;</a>. Accepts an optional argument that moves the virtual clock forward by the specified number of milliseconds, clearing asynchronous activities scheduled within that timeframe.</td></tr><tr><td style="text-align:left;"><code>discardPeriodicTasks</code></td><td style="text-align:left;">Discards any periodic tasks (e.g. <code>setInterval</code>) that were created inside the <code>fakeAsync</code> Zone.</td></tr><tr><td style="text-align:left;"><code>flushMicrotasks</code></td><td style="text-align:left;">When a <code>fakeAsync()</code> test ends with pending <em>micro-tasks</em> such as unresolved promises, the test fails with a clear error message. <br> In general, a test should wait for micro-tasks to finish. When pending microtasks are expected, call <code>flushMicrotasks</code> to flush the <em>micro-task</em> queue and avoid the error.</td></tr></tbody></table>',5)]))}const m=t(a,[["render",o]]);export{g as __pageData,m as default};
